1	import { useCallback, useEffect, useMemo, useState } from "react";
2	import BrandHeader from "../components/BrandHeader";
3	import VolverConfiguracion from "../components/VolverConfiguracion";
4	import CampoArchivos from "../components/CampoArchivos";
5	import * as api from "../api";
6	import { confirmar, notificar } from "../lib/ui";
7	import "./informeMensual.css";
8	
9	/**
10	 * Informe mensual (módulo «Informe mensual»): el «Balance hidrometeorológico del mes» de la DGAT, cargado todo a mano (todavía no hay datos
11	 * suficientes, ordenados y validados para calcular las medias solas). Sigue el modelo .docx: valores medios por estación, resumen del mes,
12	 * pronóstico climático trimestral (mapas + análisis) y fenómeno del Niño (mapas + análisis). Sale en PDF con el formato de la previsión del tiempo.
13	 * Cada sección dice en qué lugar del PDF queda, con un esquema de la hoja.
14	 */
15	const MESES = ["enero", "febrero", "marzo", "abril", "mayo", "junio", "julio", "agosto", "septiembre", "octubre", "noviembre", "diciembre"];
16	const ESTACIONES = ["Posadas", "Valle Hermoso", "San Pedro", "Andresito", "Campo Grande"];
17	const COLUMNAS = [
18	  { campo: "tmedia", titulo: "Temperatura media (°C)", corto: "T. media", unidad: "°C", entero: false },
19	  { campo: "tmin", titulo: "Temperatura mínima media (°C)", corto: "T. mínima media", unidad: "°C", entero: false },
20	  { campo: "tmax", titulo: "Temperatura máxima media (°C)", corto: "T. máxima media", unidad: "°C", entero: false },
21	  { campo: "eventos", titulo: "Eventos hidrometeorológicos (N°)", corto: "Eventos (N°)", unidad: "N°", entero: true },
22	  { campo: "precipitacion", titulo: "Precipitación acumulada (mm)", corto: "Precipitación (mm)", unidad: "mm", entero: false },
23	];
24	const LIMITE_TEXTO = 8000;
25	const RE_NUMERO = /^-?\d+([.,]\d+)?$/;
26	
27	const estacionVacia = (estacion = "") => ({ estacion, tmedia: "", tmin: "", tmax: "", eventos: "", precipitacion: "" });
28	const borradorNuevo = (anio, mes) => ({ version: 1, anio, mes, estaciones: ESTACIONES.map(estacionVacia), resumen: "", trimestral: { imagenes: [], texto: "" }, nino: { imagenes: [], texto: "" } });
29	/** Lo que está mal de una celda (o ""): número con coma o punto; los eventos, entero; la lluvia, sin signo. */
30	function problemaCelda(col, valor) {
31	  const v = String(valor ?? "").trim();
32	  if (!v) return "";
33	  if (!RE_NUMERO.test(v)) return "Tiene que ser un número (ej.: 24,5)";
34	  if (col.entero && !/^\d+$/.test(v)) return "Tiene que ser un número entero";
35	  if (col.campo === "precipitacion" && v.startsWith("-")) return "No puede ser negativa";
36	  return "";
37	}
38	
39	// --- esquema de la hoja: dónde queda cada cosa en el PDF --------------------------------------------------------------
40	const BLOQUES = [
41	  { id: "titulo", etiqueta: "Título del informe", alto: 7 },
42	  { id: "valores", etiqueta: "Valores medios del mes", alto: 17 },
43	  { id: "resumen", etiqueta: "Resumen del mes", alto: 14 },
44	  { id: "trimestral", etiqueta: "Mapas trimestrales + análisis", alto: 24, imagen: true },
45	  { id: "nino", etiqueta: "Mapas del Niño + análisis", alto: 24, imagen: true },
46	];
47	/** Una hoja en miniatura con los bloques en el orden del PDF; el de esta sección va resaltado (y la imagen, rayada). */
48	function EsquemaHoja({ activo }) {
49	  return <figure className="im-esquema" aria-label={`Esquema del PDF: esta sección es «${BLOQUES.find((b) => b.id === activo)?.etiqueta}»`}>
50	    <div className="im-hoja" aria-hidden="true">
51	      {BLOQUES.map((b) => <div key={b.id} className={`im-bloque${b.id === activo ? " im-bloque--activo" : ""}`} style={{ flex: b.alto }}>
52	        {b.imagen && <span className="im-bloque-imagen" />}<span className="im-bloque-texto" />
53	      </div>)}
54	    </div>
55	    <figcaption>Lugar en el PDF (de arriba hacia abajo)</figcaption>
56	  </figure>;
57	}
58	
59	/** Baja la imagen a un tamaño razonable (máx. 1500 px de ancho) y la devuelve como data URL PNG o JPG, para que el informe no pese de más. */
60	async function procesarImagen(archivo) {
61	  if (!/^image\/(png|jpeg)$/.test(archivo.type)) throw new Error("La imagen tiene que ser PNG o JPG.");
62	  if (archivo.size > 20 * 1024 * 1024) throw new Error("La imagen es demasiado grande (más de 20 MB).");
63	  const bmp = await createImageBitmap(archivo);
64	  const k = Math.min(1, 1500 / bmp.width), c = document.createElement("canvas");
65	  c.width = Math.round(bmp.width * k); c.height = Math.round(bmp.height * k);
66	  const ctx = c.getContext("2d");
67	  ctx.fillStyle = "#fff"; ctx.fillRect(0, 0, c.width, c.height); ctx.drawImage(bmp, 0, 0, c.width, c.height);
68	  let url = archivo.type === "image/png" ? c.toDataURL("image/png") : c.toDataURL("image/jpeg", 0.9);
69	  if (url.length > 3_400_000) url = c.toDataURL("image/jpeg", 0.88);
70	  if (url.length > 4_600_000) throw new Error("La imagen sigue siendo muy pesada: usá una más chica.");
71	  return url;
72	}
73	
74	const MAX_IMAGENES = 6;
75	/** Varias imágenes en línea: se agregan, se reordenan con las flechas y se quitan. En el PDF van en una sola fila y se ajustan solas al ancho. */
76	function CampoImagenes({ valor, onChange, descripcion }) {
77	  const [error, setError] = useState(""), [leyendo, setLeyendo] = useState(false), [razones, setRazones] = useState({}); // ancho/alto de cada imagen, para que la vista previa las ajuste como el PDF
78	  async function elegir(e) {
79	    const archivos = (e.target.files || []).slice(0, MAX_IMAGENES - valor.length);
80	    if (!archivos.length) { if (e.target.files?.length) setError(`Entran hasta ${MAX_IMAGENES} imágenes: quitá alguna para agregar otra.`); return; }
81	    setLeyendo(true); setError("");
82	    try { const nuevas = []; for (const a of archivos) nuevas.push(await procesarImagen(a)); onChange([...valor, ...nuevas]); if ((e.target.files || []).length > archivos.length) setError(`Se agregaron ${archivos.length}: el máximo es ${MAX_IMAGENES}.`); }
83	    catch (err) { setError(err.message || "No se pudo leer la imagen."); }
84	    finally { setLeyendo(false); }
85	  }
86	  const mover = (i, d) => { const n = [...valor]; [n[i], n[i + d]] = [n[i + d], n[i]]; onChange(n); };
87	  return <div className="im-imagen">
88	    {valor.length > 0 && <>
89	      <p className="im-ayuda-fila">Así van en el PDF: todas en una fila, del mismo alto, ajustadas al ancho de la hoja.</p>
90	      <ol className="im-fila-imagenes" aria-label={`Imágenes: ${descripcion}`}>
91	        {valor.map((src, i) => <li key={`${i}:${src.length}`} style={{ flexGrow: razones[`${i}:${src.length}`] || 1.5 }}>
92	          <img onLoad={(e) => { const razon = e.currentTarget.naturalWidth / e.currentTarget.naturalHeight; setRazones((r) => ({ ...r, [`${i}:${src.length}`]: razon })); }} src={src} alt={`${descripcion}, imagen ${i + 1} de ${valor.length}`} />
93	          <div className="im-fila-acciones">
94	            <button type="button" className="im-btn im-btn--chico" disabled={i === 0} onClick={() => mover(i, -1)} aria-label={`Mover la imagen ${i + 1} a la izquierda`}>←</button>
95	            <button type="button" className="im-btn im-btn--chico" disabled={i === valor.length - 1} onClick={() => mover(i, 1)} aria-label={`Mover la imagen ${i + 1} a la derecha`}>→</button>
96	            <button type="button" className="im-btn im-btn--chico im-btn--peligro" onClick={() => onChange(valor.filter((_, k) => k !== i))} aria-label={`Quitar la imagen ${i + 1}`}>Quitar</button>
97	          </div>
98	        </li>)}
99	      </ol>
100	    </>}
101	    {valor.length < MAX_IMAGENES
102	      ? <CampoArchivos label={valor.length ? "Agregar más imágenes" : "Subir imágenes"} ayuda={`PNG o JPG, hasta ${MAX_IMAGENES} (podés elegir varias juntas). Se achican solas si son muy grandes.`} accept="image/png,image/jpeg" multiple limpiarAlElegir onChange={elegir} />
103	      : <p className="im-ayuda-fila">Llegaste al máximo de {MAX_IMAGENES} imágenes.</p>}
104	    {leyendo && <p className="im-ayuda-fila" role="status">Leyendo imágenes…</p>}
105	    {error && <p className="im-error" role="alert">{error}</p>}
106	  </div>;
107	}
108	
109	function CampoTexto({ id, rotulo, ayuda, valor, onChange, filas = 6 }) {
110	  return <label className="im-campo" htmlFor={id}>
111	    <span>{rotulo}</span>
112	    <textarea id={id} rows={filas} value={valor} maxLength={LIMITE_TEXTO} onChange={(e) => onChange(e.target.value)} />
113	    <small>{ayuda ? `${ayuda} · ` : ""}{valor.length} / {LIMITE_TEXTO}</small>
114	  </label>;
115	}
116	
117	const fechaHora = (iso) => new Date(iso).toLocaleString("es-AR", { timeZone: "America/Argentina/Buenos_Aires", day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit", hourCycle: "h23" });
118	
119	export default function InformeMensualPage() {
120	  const hoy = new Date();
121	  const [anio, setAnio] = useState(hoy.getFullYear()), [mes, setMes] = useState(hoy.getMonth() === 0 ? 12 : hoy.getMonth()); // por defecto, el mes que acaba de terminar
122	  const [anioMes, setAnioMes] = useState(null); // el que está cargado en pantalla (cambia recién cuando termina de cargar)
123	  const [b, setB] = useState(null), [guardado, setGuardado] = useState(null); // `guardado`: { actualizadoEn, actualizadoPor } del informe de este mes, o null
124	  const [sucio, setSucio] = useState(false), [lista, setLista] = useState([]);
125	  const [error, setError] = useState(""), [ocupado, setOcupado] = useState("");
126	
127	  const refrescarLista = useCallback(() => api.listarInformesMensuales().then(setLista).catch(() => {}), []);
128	  useEffect(() => { refrescarLista(); }, [refrescarLista]);
129	
130	  const cargar = useCallback(async (a, m) => {
131	    setError("");
132	    try {
133	      const r = await api.getInformeMensual(a, m);
134	      const sec = (x) => ({ imagenes: Array.isArray(x?.imagenes) ? x.imagenes : x?.imagen ? [x.imagen] : [], texto: x?.texto || "" }); // los guardados antes traían una sola imagen
135	      setB(r ? { ...borradorNuevo(a, m), ...r.borrador, trimestral: sec(r.borrador.trimestral), nino: sec(r.borrador.nino), anio: a, mes: m } : borradorNuevo(a, m));
136	      setGuardado(r ? { actualizadoEn: r.actualizadoEn, actualizadoPor: r.actualizadoPor } : null);
137	      setSucio(false); setAnioMes(`${a}-${m}`);
138	    } catch (e) { setError(e.message); }
139	  }, []);
140	  useEffect(() => { cargar(anio, mes); }, []); // eslint-disable-line react-hooks/exhaustive-deps
141	
142	  useEffect(() => {
143	    if (!sucio) return undefined;
144	    const aviso = (e) => { e.preventDefault(); e.returnValue = ""; };
145	    window.addEventListener("beforeunload", aviso);
146	    return () => window.removeEventListener("beforeunload", aviso);
147	  }, [sucio]);
148	
149	  /** Cambia de mes (con aviso si hay cambios sin guardar). */
150	  async function irA(a, m) {
151	    if (`${a}-${m}` === anioMes) { setAnio(a); setMes(m); return; }
152	    if (sucio && !(await confirmar({ titulo: "Cambios sin guardar", texto: `Hay cambios sin guardar en el informe de ${MESES[(b?.mes ?? m) - 1]} de ${b?.anio}. Si cambiás de mes se pierden.`, confirmar: "Descartar y cambiar", peligro: true }))) return;
153	    setAnio(a); setMes(m); await cargar(a, m);
154	  }
155	
156	  const cambiar = (f) => { setB((x) => f(x)); setSucio(true); };
157	  const ponerCelda = (i, campo, v) => cambiar((x) => ({ ...x, estaciones: x.estaciones.map((e, k) => (k === i ? { ...e, [campo]: v } : e)) }));
158	  const ponerSeccion = (clave, campo, v) => cambiar((x) => ({ ...x, [clave]: { ...x[clave], [campo]: v } }));
159	
160	  const problemas = useMemo(() => {
161	    if (!b) return [];
162	    const p = [];
163	    b.estaciones.forEach((e) => COLUMNAS.forEach((c) => { const t = problemaCelda(c, e[c.campo]); if (t) p.push(`${e.estacion || "Estación"} · ${c.corto}: ${t.toLowerCase()}`); }));
164	    return p;
165	  }, [b]);
166	  const faltantes = useMemo(() => {
167	    if (!b) return [];
168	    const f = [];
169	    const vacias = b.estaciones.reduce((n, e) => n + COLUMNAS.filter((c) => !String(e[c.campo] ?? "").trim()).length, 0);
170	    if (vacias) f.push(`${vacias} ${vacias === 1 ? "celda" : "celdas"} de la tabla sin completar`);
171	    if (!b.resumen.trim()) f.push("el resumen del mes");
172	    if (!b.trimestral.imagenes.length) f.push("los mapas del pronóstico trimestral");
173	    if (!b.trimestral.texto.trim()) f.push("el análisis del pronóstico trimestral");
174	    if (!b.nino.imagenes.length) f.push("los mapas del fenómeno del Niño");
175	    if (!b.nino.texto.trim()) f.push("el texto del fenómeno del Niño");
176	    return f;
177	  }, [b]);
178	
179	  async function guardar() {
180	    if (problemas.length) { setError("Corregí los valores marcados en rojo antes de guardar."); return; }
181	    setOcupado("guardar"); setError("");
182	    try {
183	      const r = await api.guardarInformeMensual(b.anio, b.mes, b);
184	      setGuardado({ actualizadoEn: r.actualizadoEn, actualizadoPor: r.actualizadoPor }); setSucio(false); refrescarLista();
185	      notificar("success", "Informe guardado.");
186	    } catch (e) { setError(e.message); }
187	    finally { setOcupado(""); }
188	  }
189	  async function pdf(descargar) {
190	    if (problemas.length) { setError("Corregí los valores marcados en rojo para armar el PDF."); return; }
191	    setOcupado(descargar ? "descargar" : "ver"); setError("");
192	    // La pestaña se abre ya (con el clic) y se completa cuando está el PDF, para que el navegador no la bloquee.
193	    const pestana = descargar ? null : window.open("", "_blank");
194	    try {
195	      const url = URL.createObjectURL(await api.generarInformeMensualPdf(b));
196	      if (descargar) { const a = document.createElement("a"); a.href = url; a.download = `BALANCE ${MESES[b.mes - 1].toUpperCase()} ${b.anio}.pdf`; a.click(); }
197	      else if (pestana) pestana.location.href = url; else window.open(url, "_blank");
198	      setTimeout(() => URL.revokeObjectURL(url), 120000);
199	    } catch (e) { pestana?.close(); setError(e.message); }
200	    finally { setOcupado(""); }
201	  }
202	  /** Cancela lo que se está armando: descarta los cambios y vuelve a lo último guardado (o a un informe en blanco si nunca se guardó). */
203	  async function descartar() {
204	    const aviso = guardado ? "Se pierden los cambios hechos desde el último guardado y el informe vuelve a como estaba." : "Se pierde todo lo que cargaste (tabla, textos e imágenes) y el informe queda en blanco.";
205	    if (!(await confirmar({ titulo: "Descartar el informe", texto: `${aviso} No se puede deshacer.`, confirmar: "Descartar", cancelar: "Seguir editando", peligro: true }))) return;
206	    await cargar(b.anio, b.mes);
207	    notificar("info", guardado ? "Se descartaron los cambios." : "Informe descartado.");
208	  }
209	  async function borrar() {
210	    if (!(await confirmar({ titulo: "Borrar el informe guardado", texto: `Se borra el informe de ${MESES[b.mes - 1]} de ${b.anio} (con sus imágenes). No se puede deshacer.`, confirmar: "Borrar", peligro: true }))) return;
211	    try { await api.borrarInformeMensual(b.anio, b.mes); await cargar(b.anio, b.mes); refrescarLista(); notificar("success", "Informe borrado."); } catch (e) { setError(e.message); }
212	  }
213	
214	  const anios = useMemo(() => Array.from({ length: 8 }, (_, i) => hoy.getFullYear() + 1 - i), []); // eslint-disable-line react-hooks/exhaustive-deps
215	  const celdaMala = (c, e) => !!problemaCelda(c, e[c.campo]);
216	
217	  return <div className="admin-layout admin-layout--sin-mapa">
218	    <BrandHeader subtitulo="Informe mensual"><VolverConfiguracion /></BrandHeader>
219	    <div className="admin-panel im-pagina" id="contenido-principal" tabIndex={-1}>
220	      <div className="editor-heading">
221	        <h1>Informe mensual</h1>
222	        <p>Balance hidrometeorológico del mes. Por ahora se carga todo a mano: los valores medios todavía no se calculan solos. Cada sección muestra en qué lugar del PDF queda.</p>
223	      </div>
224	
225	      <div className="im-barra">
226	        <label className="im-select"><span>Mes</span>
227	          <select value={mes} onChange={(e) => irA(anio, Number(e.target.value))}>{MESES.map((m, i) => <option key={m} value={i + 1}>{m.charAt(0).toUpperCase() + m.slice(1)}</option>)}</select></label>
228	        <label className="im-select"><span>Año</span>
229	          <select value={anio} onChange={(e) => irA(Number(e.target.value), mes)}>{anios.map((a) => <option key={a} value={a}>{a}</option>)}</select></label>
230	        <p className="im-estado" role="status">
231	          {!b ? "Cargando…" : sucio ? <strong>Cambios sin guardar</strong> : guardado ? <>Guardado el <strong>{fechaHora(guardado.actualizadoEn)} h</strong>{guardado.actualizadoPor ? ` · ${guardado.actualizadoPor}` : ""}</> : "Informe nuevo, todavía sin guardar"}
232	        </p>
233	      </div>
234	      {lista.length > 0 && <div className="im-guardados" aria-label="Informes guardados">
235	        <span>Guardados:</span>
236	        {lista.map((i) => <button key={`${i.anio}-${i.mes}`} type="button" className={`im-chip${i.anio === b?.anio && i.mes === b?.mes ? " im-chip--on" : ""}`} onClick={() => irA(i.anio, i.mes)}>{MESES[i.mes - 1]} {i.anio}</button>)}
237	      </div>}
238	
239	      {error && <div className="alert alert--error" role="alert">{error}</div>}
240	
241	      {b && <>
242	        <section className="im-seccion" aria-labelledby="im-s0">
243	          <EsquemaHoja activo="titulo" />
244	          <div className="im-seccion-cuerpo">
245	            <h2 id="im-s0">Título</h2>
246	            <p className="im-ubicacion">Arriba de todo, con los logos y la dirección: se arma solo con el mes y el año elegidos.</p>
247	            <p className="im-titulo-vista">BALANCE HIDROMETEOROLÓGICO DEL MES DE {MESES[b.mes - 1].toUpperCase()} DE {b.anio}</p>
248	          </div>
249	        </section>
250	
251	        <section className="im-seccion" aria-labelledby="im-s1">
252	          <EsquemaHoja activo="valores" />
253	          <div className="im-seccion-cuerpo">
254	            <h2 id="im-s1">Valores medios del mes</h2>
255	            <p className="im-ubicacion">Tabla debajo del título, una fila por estación. Los números con coma o punto (24,5); los eventos, enteros.</p>
256	            <div className="im-tabla-envoltorio">
257	              <table className="im-tabla">
258	                <thead><tr><th scope="col">Estación</th>{COLUMNAS.map((c) => <th scope="col" key={c.campo}>{c.titulo}</th>)}<th><span className="im-sr">Quitar</span></th></tr></thead>
259	                <tbody>
260	                  {b.estaciones.map((e, i) => <tr key={i}>
261	                    <th scope="row"><input type="text" aria-label={`Nombre de la estación ${i + 1}`} value={e.estacion} maxLength={60} onChange={(ev) => ponerCelda(i, "estacion", ev.target.value)} /></th>
262	                    {COLUMNAS.map((c) => <td key={c.campo}><input type="text" inputMode="decimal" aria-label={`${e.estacion || "Estación"}: ${c.titulo}`} aria-invalid={celdaMala(c, e) || undefined} title={problemaCelda(c, e[c.campo]) || undefined}
263	                      className={celdaMala(c, e) ? "im-malo" : ""} value={e[c.campo]} maxLength={12} onChange={(ev) => ponerCelda(i, c.campo, ev.target.value)} /></td>)}
264	                    <td><button type="button" className="im-btn im-btn--chico" aria-label={`Quitar ${e.estacion || "la estación"}`} onClick={() => cambiar((x) => ({ ...x, estaciones: x.estaciones.filter((_, k) => k !== i) }))}>✕</button></td>
265	                  </tr>)}
266	                </tbody>
267	              </table>
268	            </div>
269	            <div className="im-acciones-tabla">
270	              <button type="button" className="im-btn" disabled={b.estaciones.length >= 20} onClick={() => cambiar((x) => ({ ...x, estaciones: [...x.estaciones, estacionVacia()] }))}>+ Agregar estación</button>
271	              <small>Referencias que salen debajo de la tabla: ° C Grados Celsius · N° Número de eventos · mm Milímetros de precipitación.</small>
272	            </div>
273	          </div>
274	        </section>
275	
276	        <section className="im-seccion" aria-labelledby="im-s2">
277	          <EsquemaHoja activo="resumen" />
278	          <div className="im-seccion-cuerpo">
279	            <h2 id="im-s2">Resumen meteorológico del mes</h2>
280	            <p className="im-ubicacion">Texto libre, debajo de la tabla de valores medios. Un renglón nuevo arma un párrafo nuevo.</p>
281	            <CampoTexto id="im-resumen" rotulo="Resumen" valor={b.resumen} onChange={(v) => cambiar((x) => ({ ...x, resumen: v }))} filas={9} />
282	          </div>
283	        </section>
284	
285	        <section className="im-seccion" aria-labelledby="im-s3">
286	          <EsquemaHoja activo="trimestral" />
287	          <div className="im-seccion-cuerpo">
288	            <h2 id="im-s3">Pronóstico climático trimestral</h2>
289	            <p className="im-ubicacion">Primero los mapas (precipitación y temperatura del trimestre; podés subir varios, van en una fila) y debajo el texto de análisis, bajo la barra «Pronóstico climático trimestral».</p>
290	            <CampoImagenes valor={b.trimestral.imagenes} descripcion="Mapas del pronóstico climático trimestral" onChange={(v) => ponerSeccion("trimestral", "imagenes", v)} />
291	            <CampoTexto id="im-trim" rotulo="Análisis de los mapas" valor={b.trimestral.texto} onChange={(v) => ponerSeccion("trimestral", "texto", v)} />
292	          </div>
293	        </section>
294	
295	        <section className="im-seccion" aria-labelledby="im-s4">
296	          <EsquemaHoja activo="nino" />
297	          <div className="im-seccion-cuerpo">
298	            <h2 id="im-s4">Estado actual y proyección del fenómeno del Niño</h2>
299	            <p className="im-ubicacion">Al final: los mapas del fenómeno (varios, en una fila) y debajo su texto, bajo la barra «Estado actual y proyección del fenómeno del Niño».</p>
300	            <CampoImagenes valor={b.nino.imagenes} descripcion="Mapas del fenómeno del Niño" onChange={(v) => ponerSeccion("nino", "imagenes", v)} />
301	            <CampoTexto id="im-nino" rotulo="Texto del fenómeno del Niño" valor={b.nino.texto} onChange={(v) => ponerSeccion("nino", "texto", v)} />
302	          </div>
303	        </section>
304	
305	        <div className="im-pie" role="region" aria-label="Acciones del informe">
306	          <div className="im-pie-estado">
307	            {problemas.length > 0 && <p className="im-error" role="alert">Hay valores que no son válidos: {problemas.slice(0, 3).join("; ")}{problemas.length > 3 ? ` y ${problemas.length - 3} más` : ""}.</p>}
308	            {faltantes.length > 0 && <p className="im-faltan">Todavía falta: {faltantes.join(", ")}. El PDF se puede bajar igual, incompleto.</p>}
309	          </div>
310	          <div className="im-pie-botones">
311	            <button type="button" className="im-btn" disabled={!!ocupado || !sucio} onClick={descartar}
312	              title={sucio ? "Descarta lo que cargaste desde el último guardado" : "No hay cambios para descartar"}>Cancelar y descartar</button>
313	            {guardado && <button type="button" className="im-btn im-btn--peligro" onClick={borrar} title="Borra el informe guardado de este mes">Borrar guardado</button>}
314	            <button type="button" className="im-btn" disabled={!!ocupado} onClick={() => pdf(false)}>{ocupado === "ver" ? "Armando…" : "Ver PDF"}</button>
315	            <button type="button" className="im-btn" disabled={!!ocupado} onClick={() => pdf(true)}>{ocupado === "descargar" ? "Armando…" : "Descargar PDF"}</button>
316	            <button type="button" className="im-btn im-btn--primario" disabled={!!ocupado || !sucio && !!guardado} onClick={guardar}>{ocupado === "guardar" ? "Guardando…" : "Guardar informe"}</button>
317	          </div>
318	        </div>
319	      </>}
320	    </div>
321	  </div>;
