            <button type="button" className="im-btn im-btn--primario" disabled={!!ocupado || !sucio && !!guardado} onClick={guardar}>{ocupado === "guardar" ? "Guardando…" : "Guardar informe"}</button>
          </div>
        </div>
      </>}
    </div>
  </div>;
