const ExcelJS = require(process.argv[2] + '/node_modules/exceljs');
const fs = require('fs');
const S = process.argv[3];
const a = JSON.parse(fs.readFileSync(S + '/acp.json'));
const loc = (s) => new Date(Date.parse(s) - 3 * 3600e3); // hora de Misiones leída como UTC
const mes = (d) => d.getUTCFullYear() === 2026 && d.getUTCMonth() === 9;
const filas = [];
for (const r of a) for (const i of r.infos) {
  const ini = loc(i.inicio); if (!mes(ini)) continue;
  const m = /AVISO\s+(AMARILLO|NARANJA|ROJO)/.exec(i.titulo.toUpperCase());
  const deps = [...new Set(i.zonas.flatMap(z => z.departamentos || []))].sort((x, y) => x.localeCompare(y, 'es'));
  const cap = (s) => s.charAt(0) + s.slice(1).toLowerCase();
  filas.push({ emi: loc(r.emitidoEn), ini, fin: loc(i.fin), nivel: m ? cap(m[1]) : '—', evento: cap(i.evento), titulo: i.titulo, deps, zona: i.zonas.map(z => z.nombre).join(' | '), sev: i.severidad, desc: i.descripcion, url: r.url });
}
filas.sort((x, y) => x.ini - y.ini);
const wb = new ExcelJS.Workbook();
const ws = wb.addWorksheet('Avisos ACP octubre 2026', { views: [{ state: 'frozen', xSplit: 2, ySplit: 1 }] });
ws.columns = [['N°', 5], ['Emitido', 17], ['Inicio', 17], ['Fin', 17], ['Duración (min)', 10], ['Nivel', 10], ['Evento', 24], ['Título del aviso', 45], ['Departamentos', 45], ['Cant. dptos', 8], ['Zona (texto del SMN)', 45], ['Severidad CAP', 11], ['Descripción', 60], ['Enlace CAP', 40]].map(([header, width]) => ({ header, width }));
const col = { Amarillo: 'FFFFF2B3', Naranja: 'FFFFD3A6', Rojo: 'FFF5B5BD' };
filas.forEach((f, n) => {
  const r = ws.addRow([n + 1, f.emi, f.ini, f.fin, Math.round((f.fin - f.ini) / 60000), f.nivel, f.evento, f.titulo, f.deps.join(', '), f.deps.length, f.zona, f.sev, f.desc, f.url]);
  [2, 3, 4].forEach(k => r.getCell(k).numFmt = 'dd/mm/yyyy hh:mm');
  r.alignment = { vertical: 'top', wrapText: true };
  if (col[f.nivel]) r.getCell(6).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: col[f.nivel] } };
});
const h = ws.getRow(1); h.height = 30;
h.eachCell(c => { c.font = { bold: true, color: { argb: 'FFFFFFFF' } }; c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1F5C3F' } }; c.alignment = { horizontal: 'center', vertical: 'middle', wrapText: true }; });
ws.autoFilter = { from: 'A1', to: 'N1' };
const rs = wb.addWorksheet('Resumen'); rs.getColumn(1).width = 52; rs.getColumn(2).width = 12;
rs.getCell('A1').value = 'Avisos a muy corto plazo (ACP) — octubre 2026'; rs.getCell('A1').font = { bold: true, size: 14 };
rs.getCell('A2').value = `Total de avisos: ${filas.length}`; rs.getCell('A2').font = { bold: true };
rs.getCell('A3').value = 'Fuente: historial del SMN guardado en la base. Avisos con inicio entre el 01/10 y el 31/10 (hora de Misiones).';
let x = 5;
const cuenta = (it) => { const m = new Map(); for (const k of it) m.set(k, (m.get(k) || 0) + 1); return [...m]; };
const bloque = (t, lista) => { rs.getCell(x, 1).value = t; rs.getCell(x, 1).font = { bold: true, size: 12 }; lista.forEach(([k, v], j) => { rs.getCell(x + 1 + j, 1).value = k; rs.getCell(x + 1 + j, 2).value = v; }); x += lista.length + 2; };
const desc = (l) => l.sort((p, q) => q[1] - p[1] || String(p[0]).localeCompare(q[0], 'es'));
bloque('Por nivel', desc(cuenta(filas.map(f => f.nivel))));
bloque('Por evento', desc(cuenta(filas.map(f => f.evento))));
bloque('Por departamento (avisos que lo incluyen)', desc(cuenta(filas.flatMap(f => f.deps))));
bloque('Por día de inicio', cuenta(filas.map(f => `${String(f.ini.getUTCDate()).padStart(2, '0')}/10`)));
wb.xlsx.writeFile('/home/hernan/Escritorio/Ecologia/Informe ACP octubre 2026.xlsx').then(() => {
  console.log(filas.length, JSON.stringify(cuenta(filas.map(f => f.nivel))), JSON.stringify(desc(cuenta(filas.map(f => f.evento))).slice(0, 5)));
});
EOF
