/** Sólo lo que se usa, recortado (lo que se guarda en la base). */
function normalizarInformeMensual(b) {
  const t = (v) => (typeof v === "string" ? v.trim() : "");
  const n = (v) => (vacio(v) ? "" : String(v).trim().replace(".", ","));
