.im-pestana { font: inherit; font-size: 0.9rem; font-weight: 600; padding: 9px 16px; border: 1px solid transparent; border-bottom: 0; border-radius: 8px 8px 0 0; background: transparent; color: var(--text-muted); cursor: pointer; margin-bottom: -1px; }
.im-pestana:hover { color: var(--text); background: var(--surface-2); }
.im-pestana--on { color: var(--text); background: var(--surface); border-color: var(--border); box-shadow: inset 0 3px 0 var(--accent, #872338); }
