[hidden].im-pagina, [role="tabpanel"][hidden] { display: none; }
.im-select input[type="date"] { font: inherit; font-size: 0.9rem; min-height: 36px; padding: 0 10px; border: 1px solid var(--border); border-radius: 8px; background: var(--surface); color: var(--text); }
.im-campo input[type="text"] { font: inherit; font-size: 0.92rem; padding: 8px 12px; border: 1px solid var(--border); border-radius: 8px; background: var(--bg); color: var(--text); width: 100%; box-sizing: border-box; }
.im-campo--rotulo { margin-top: 0; margin-bottom: 10px; max-width: 640px; }
.im-th-input { font-size: 0.72rem !important; font-weight: 700; text-align: center; min-height: 32px !important; }
.im-seccion--simple { grid-template-columns: minmax(0, 1fr); }
.im-segmentos { display: flex; gap: 6px; }
