  L.push(`🎤 **Decir:** ${s.notas}`, "");
});
L.push("## Capturas a sacar", "", "| # | Diapositiva | Archivo |", "|---|---|---|");
capturas.forEach(([n, t, c]) => L.push(`| ${n} | ${t} | \`src/capturas/${c}\` |`));
