toolu_01JwZX3rcQEoiHd3pGFXvvkT.command:
cd /home/hernan/Escritorio/Ecologia/presentacion-dia-gis && node - <<'EOF'
const fs = require("fs");
let t = fs.readFileSync("src/slides.data.js", "utf8");
const R = (a, b) => { if (!t.includes(a)) throw new Error("falta: " + a.slice(0, 50)); t = t.replace(a, b); };

// portada
R(`titulo: "Mapas sin GIS",
    subtitulo: "Cómo sistematizamos información territorial y la mostramos en mapas",`,
  `titulo: "Sistemas de Información Geográfica",
    subtitulo: "Cómo sistematizamos la información territorial y la llevamos al mapa",`);
R(`"Saludo y presentación (nombre, área). Anticipar la idea fuerza: vamos a mostrar dos sistemas que se ven y se usan como un SIG, pero que están hechos con herramientas web abiertas. Duración total estimada: 12–15 minutos."`,
  `"Saludo y presentación (nombre, área). Anticipar la idea fuerza: vamos a recorrer dos sistemas de información geográfica del ministerio, Alerta Temprana y Ecodatos, y ver cómo la información territorial pasa de ser un dato suelto a ser una capa en un mapa. Duración total estimada: 12–15 minutos."`);

// idea
R(`titulo: "La idea en una frase",
    destacado: "Un mapa no necesita un SIG para ser útil: necesita datos ordenados.",
    puntos: [
      "Los datos están en bases de datos propias, con coordenadas y polígonos.",
      "El mapa se dibuja en el navegador, con librerías abiertas.",
      "Quien consulta no instala nada: abre un link.",
    ],`,
  `titulo: "¿Qué es un SIG?",
    destacado: "Un SIG conecta cada dato con un lugar del territorio.",
    puntos: [
      "Capas: puntos, líneas y polígonos con su ubicación.",
      "Atributos: cada elemento guarda su información asociada.",
      "Análisis espacial: cruzar capas para responder dónde, cuánto y qué pasa cerca.",
      "WebGIS: el mapa se consulta desde el navegador, sin instalar nada.",
    ],`);
R(`"Aclarar con honestidad que no usamos un software GIS (QGIS/ArcGIS) en estos dos sistemas. Lo que hicimos es sistematizar: cada dato nace con su ubicación y el mapa es solo la forma de verlo. Esto es lo que da el 'aspecto SIG' sin la herramienta SIG."`,
  `"Definir en simple qué es un SIG: un sistema que organiza datos con su ubicación para poder verlos, consultarlos y analizarlos en un mapa. Los cuatro conceptos (capas, atributos, análisis espacial, WebGIS) son el hilo de toda la presentación: los vamos a ir reconociendo en cada mapa."`);

// flujo
R(`titulo: "Dos sistemas, un mismo camino",`, `titulo: "Dos SIG, un mismo camino",`);
R(`{ t: "Fuentes", d: "Satélites, SMN, INTA, formularios de campo" },
      { t: "Sistematización", d: "Se limpian, validan y guardan con su ubicación" },
      { t: "Mapa", d: "Capas, colores y popups en el navegador" },
      { t: "Difusión", d: "Panel, embebidos, placas, PDF" },`,
  `{ t: "Captura del dato", d: "Satélites, SMN, INTA, formularios de campo" },
      { t: "Geodatabase", d: "Se validan y guardan con su ubicación y atributos" },
      { t: "Capas y simbología", d: "Colores, leyendas y fichas en el mapa web" },
      { t: "Difusión", d: "Panel, mapas embebidos, placas y PDF" },`);
R(`"Presentar el esquema común. Alerta Temprana trabaja con datos que llegan de afuera (clima, satélites). Ecodatos trabaja con datos que cargamos nosotros en territorio. El camino es el mismo: fuente, orden, mapa, difusión."`,
  `"Presentar el flujo de trabajo SIG común: captura, almacenamiento georreferenciado, representación en capas y difusión. Alerta Temprana trabaja con datos que llegan de afuera (clima, satélites); Ecodatos con datos que relevamos nosotros en territorio."`);

// sección AT
R(`"Contar en una línea para qué existe: el equipo necesita saber qué viene (tormentas, calor, crecidas, incendios) y avisar rápido a la población y a los organismos."`,
  `"Contar en una línea para qué existe: SIG de monitoreo para saber qué viene (tormentas, calor, crecidas, incendios) y avisar rápido a la población y a los organismos."`);

// textos específicos
R(`"Mostrar el panel principal como 'tablero de capas'. Cada tarjeta es un tema (pronóstico, alertas, focos de calor, cuencas, lluvias). Es el equivalente a la tabla de contenidos de un SIG."`,
  `"Mostrar el panel principal como el administrador de capas de un SIG. Cada tarjeta es un tema (pronóstico, alertas, focos de calor, cuencas, lluvias) y se puede mirar por separado o en conjunto."`);
R(`"Es el mapa más visto. Cada municipio toma el dato de la estación oficial más cercana (se calcula la distancia) y se pinta según la condición. Es una clasificación temática, como en un SIG. Mencionar que es un mapa embebible en la web del ministerio."`,
  `"Es el mapa más visto. Capa de polígonos municipales con simbología por categoría (mapa temático). Cada municipio toma el dato de la estación oficial más cercana: es un análisis de proximidad. Mencionar que es un mapa web embebible en el sitio del ministerio."`);
R(`"El SMN publica avisos en formato abierto (CAP). El sistema los lee solo, los separa por vigencia y los pinta por departamento. Remarcar la automatización: nadie transcribe nada. Nivel de alerta = simbología graduada."`,
  `"El SMN publica avisos en formato abierto (CAP). El sistema los lee solo, los separa por vigencia y los vincula a las zonas del territorio. Es una unión por atributo con simbología graduada (amarillo, naranja, rojo). Remarcar la automatización: nadie transcribe nada."`);
R(`"Los avisos a corto plazo son los más urgentes. En octubre hubo 47. Explicar que el sistema cruza horarios entre avisos y alertas para colorear coherentemente, y que la misma información genera la imagen para publicar."`,
  `"Los avisos a corto plazo son los más urgentes. En octubre hubo 47. Explicar el cruce de capas: el aviso se superpone con la alerta vigente para colorearlo con coherencia, y la misma información genera la imagen para publicar."`);
R(`"Dato satelital abierto que ya viene con latitud y longitud: es información geográfica pura. Solo hay que traerla, filtrarla a Misiones y dibujarla. Ejemplo claro de dato abierto + mapa web."`,
  `"Capa de puntos de origen satelital, ya georreferenciada (latitud y longitud). Se recorta al límite de Misiones —un clip espacial— y se dibuja. Ejemplo claro de dato abierto llevado a un WebGIS."`);
R(`"Capa hidrológica: estaciones puntuales con su último valor. Los puntos críticos de rutas son una capa propia que cruzamos con la altura del arroyo. Es análisis espacial simple, hecho con reglas en el sistema."`,
  `"Capa hidrológica: estaciones puntuales con su último valor como atributo. Los puntos críticos de rutas son otra capa que se cruza con la altura del arroyo: análisis espacial para saber qué tramo queda comprometido."`);
R(`"Antes era un Excel manual. Ahora se carga una vez y de ahí salen la tabla, el mapa y los informes en PDF. Mensaje: sistematizar el dato una sola vez y reutilizarlo en todos lados."`,
  `"Antes era un Excel manual. Ahora cada estación es un punto con su serie de lluvias como atributos, y de ahí salen la tabla, el mapa y los informes en PDF. Mensaje: una sola fuente de verdad georreferenciada."`);
R(`"Mostrar que no dependemos de un único modelo. Se compara lo que dice cada uno sobre el mismo territorio. Si el público es técnico, mencionar que es la misma lógica de overlay de capas."`,
  `"Mostrar que no dependemos de un único modelo. Cada modelo es como una capa distinta sobre el mismo territorio, y se comparan por departamento: es una superposición de capas para medir la incertidumbre."`);
R(`"Cerrar el bloque: el mapa no es el final, es el insumo. De él salen la placa para redes, la pantalla de la sala y los informes. Todo con la identidad visual del ministerio."`,
  `"Cerrar el bloque: el mapa no es el final, es el insumo. Es la salida cartográfica del SIG: placa para redes, pantalla de la sala e informes, todo con la identidad visual del ministerio."`);

// ecodatos
R(`"Cambio de enfoque: acá el dato no viene de afuera, lo cargamos nosotros. Técnicos en territorio registran perforaciones, áreas protegidas, trámites, etc., desde formularios web y desde una app móvil."`,
  `"Cambio de enfoque: acá el dato no viene de afuera, lo relevamos nosotros. Técnicos en territorio registran perforaciones, áreas protegidas, trámites, etc., desde formularios web y desde una app móvil, siempre con su ubicación."`);
R(`{ t: "Formulario", d: "Web o app móvil, con fotos y ubicación" },
      { t: "Base de datos", d: "Una tabla por tema, validada" },
      { t: "Reportes", d: "Tablas, filtros y estadísticas" },
      { t: "Mapa", d: "Puntos y polígonos clickeables" },`,
  `{ t: "Relevamiento", d: "Formulario web o app móvil, con fotos y ubicación" },
      { t: "Geodatabase", d: "Una tabla por tema, con geometría y validación" },
      { t: "Consultas", d: "Filtros, tablas y estadísticas por territorio" },
      { t: "Mapa", d: "Puntos y polígonos con su ficha" },`);
R(`"Explicar la lógica: cada formulario tiene su tabla y todos los registros tienen ubicación. Por eso cualquier tabla se puede ver en mapa sin trabajo extra."`,
  `"Explicar la lógica: cada formulario es una capa temática con su tabla de atributos y todos los registros tienen geometría. Por eso cualquier tabla se puede ver en el mapa sin trabajo extra."`);
R(`"Mostrar el mapa de un reporte: puntos agrupados en clusters que se abren al acercar. Click en un marcador: ficha con los campos del formulario. Es la capa de puntos clásica de un SIG, pero dentro de la aplicación."`,
  `"Mostrar el mapa de un reporte: capa de puntos agrupados en clusters que se abren al acercar. Click en un marcador: ficha con la tabla de atributos del registro (consulta por identificación). Filtrar por categoría equivale a una consulta por atributo."`);
R(`"Acá está el salto: no solo puntos, también áreas. Se importan polígonos y se asocian al registro correspondiente. Un registro puede abarcar varios departamentos o municipios."`,
  `"Acá está el salto: no solo puntos, también capas de polígonos. Se importan geometrías en GeoJSON y se asocian al registro correspondiente; la superficie se calcula desde la geometría. Un registro puede abarcar varios departamentos o municipios."`);
R(`"Mucho dato histórico vive en planillas. La importación lo incorpora ordenado, con controles. Es parte de sistematizar: lo viejo también entra al mismo modelo."`,
  `"Mucho dato histórico vive en planillas. La importación (CSV o GeoJSON) lo incorpora a la geodatabase con controles de calidad. Es parte de sistematizar: lo viejo también entra al mismo modelo."`);
R(`"El mapa responde 'dónde'; las estadísticas responden 'cuánto'. Los dos usan el mismo dato y los mismos filtros, por eso no hay inconsistencias entre lo que se ve y lo que se cuenta."`,
  `"El mapa responde 'dónde'; las estadísticas responden 'cuánto'. Es estadística zonal: se agrega el dato por unidad territorial. Mapa y gráficos usan el mismo dato y los mismos filtros."`);

// cierre
R(`"Los datos están en bases de datos propias` , `"Los datos están en bases de datos propias`).toString;
R(`"Herramientas abiertas, sin licencias y con acceso desde el navegador.",`, `"WebGIS con herramientas abiertas: se consulta desde el navegador.",`);
R(`"El dato se carga o se trae una sola vez, ordenado.",
      "El mapa es una vista del dato, no un archivo aparte.",`,
  `"El dato se carga o se trae una sola vez, georreferenciado.",
      "El mapa es una vista de la geodatabase, no un archivo aparte.",`);
R(`"Resumen. Insistir en la lección del evento: la clave no es el software, es la sistematización. Un SIG puede venir después y consumir estos mismos datos."`,
  `"Resumen. Insistir en que la clave de un SIG es la información geográfica bien sistematizada: una vez que el dato tiene ubicación y atributos, se puede mapear, analizar y difundir de muchas maneras."`);
R(`"Agradecer y abrir preguntas. Preparar respuestas para: ¿qué librerías usan? (mapas web abiertos), ¿dónde se guardan los datos? (base propia), ¿se podría conectar con QGIS? (sí, los datos tienen coordenadas)."`,
  `"Agradecer y abrir preguntas. Preparar respuestas para: ¿qué librerías usan? (mapas web abiertos: MapLibre y Leaflet), ¿dónde se guardan los datos? (base de datos propia del ministerio), ¿se pueden usar en QGIS u otro SIG de escritorio? (sí, los datos tienen coordenadas)."`);
fs.writeFileSync("src/slides.data.js", t);
