.hoja {
  position: absolute; inset: 0; opacity: 0; pointer-events: none; visibility: hidden; clip-path: inset(0);
  transition: transform .8s cubic-bezier(.22,.8,.2,1), opacity .6s ease, filter .8s ease, clip-path .8s cubic-bezier(.65,0,.35,1), visibility 0s .8s;
}
.hoja[data-pos="0"] { opacity: 1; visibility: visible; pointer-events: auto; transform: none; filter: none; clip-path: inset(0); transition-delay: 0s; }
/* deslizar */
.hoja[data-t="deslizar"][data-pos="-1"], .hoja[data-t="deslizar"][data-pos="-2"] { transform: translateX(-9%) scale(.97); filter: blur(6px); }
.hoja[data-t="deslizar"][data-pos="1"], .hoja[data-t="deslizar"][data-pos="2"] { transform: translateX(9%) scale(.97); filter: blur(6px); }
/* zoom */
.hoja[data-t="zoom"][data-pos="-1"], .hoja[data-t="zoom"][data-pos="-2"] { transform: scale(1.35); }
.hoja[data-t="zoom"][data-pos="1"], .hoja[data-t="zoom"][data-pos="2"] { transform: scale(.7); }
/* giro (puerta sobre el eje vertical) */
.hoja[data-t="giro"][data-pos="-1"], .hoja[data-t="giro"][data-pos="-2"] { transform: perspective(2200px) rotateY(80deg) translateX(-20%); }
.hoja[data-t="giro"][data-pos="1"], .hoja[data-t="giro"][data-pos="2"] { transform: perspective(2200px) rotateY(-80deg) translateX(20%); }
/* cortina (barrido) */
.hoja[data-t="cortina"][data-pos="-1"], .hoja[data-t="cortina"][data-pos="-2"] { opacity: 1; clip-path: inset(0 100% 0 0); }
.hoja[data-t="cortina"][data-pos="1"], .hoja[data-t="cortina"][data-pos="2"] { opacity: 1; clip-path: inset(0 0 0 100%); }
/* caída (vertical) */
.hoja[data-t="caida"][data-pos="-1"], .hoja[data-t="caida"][data-pos="-2"] { transform: translateY(-16%); }
.hoja[data-t="caida"][data-pos="1"], .hoja[data-t="caida"][data-pos="2"] { transform: translateY(16%); }
/* desenfoque (disolvencia) */
.hoja[data-t="desenfoque"][data-pos="-1"], .hoja[data-t="desenfoque"][data-pos="-2"],
.hoja[data-t="desenfoque"][data-pos="1"], .hoja[data-t="desenfoque"][data-pos="2"] { filter: blur(34px) brightness(1.4); transform: scale(1.06); }
/* cubo */
.hoja[data-t="cubo"][data-pos="-1"], .hoja[data-t="cubo"][data-pos="-2"] { transform-origin: 100% 50%; transform: perspective(2400px) translateX(-100%) rotateY(-70deg); }
.hoja[data-t="cubo"][data-pos="1"], .hoja[data-t="cubo"][data-pos="2"] { transform-origin: 0% 50%; transform: perspective(2400px) translateX(100%) rotateY(70deg); }
/* abrir (escala con inclinación) */
.hoja[data-t="abrir"][data-pos="-1"], .hoja[data-t="abrir"][data-pos="-2"] { transform: scale(.55) rotate(-9deg) translateY(10%); }
.hoja[data-t="abrir"][data-pos="1"], .hoja[data-t="abrir"][data-pos="2"] { transform: scale(.55) rotate(9deg) translateY(10%); }
`);
c += `
.area { font-size: 54px; font-weight: 600; letter-spacing: .04em; color: var(--amarillo); margin-top: 18px; }
