const fs = require("fs");
let t = fs.readFileSync("src/slides.data.js", "utf8");
const cut = (id) => { const i0 = t.indexOf(`  {\n    id: "${id}",`); if (i0 < 0) throw new Error(id); const i1 = t.indexOf("\n  },\n", i0) + 6; const s = t.slice(i0, i1); t = t.slice(0, i0) + t.slice(i1); return s; };
const R = (a, b) => { if (!t.includes(a)) throw new Error("falta " + a.slice(0, 50)); t = t.replace(a, b); };

// panel
const p0 = t.indexOf(`    id: "at-panel",`), p1 = t.indexOf("\n  },\n", p0);
let panel = t.slice(p0, p1);
panel = panel
  .replace(/titulo: "[^"]*"/, 'titulo: "Detrás de la página: el generador de mapas"')
  .replace(/captura: "[^"]*"/, 'captura: "alerta-temprana/panel-mapas.png"')
  .replace(/puntos: \[[\s\S]*?\],/, `puntos: [
      "Un módulo por cada mapa: pronóstico, riesgo de incendios, alertas y avisos.",
      "Cada uno se edita, se revisa en vista previa y se publica.",
      "Acceso por usuario, con permisos por módulo.",
    ],`);
t = t.slice(0, p0) + panel + t.slice(p1);

// lluvias sin captura útil: se saca; ensamble con captura real
cut("at-lluvias");
R(`captura: "alerta-temprana/ensamble.png"`, `captura: "alerta-temprana/panel-ensamble.png"`);

// alertas en el panel, después de la alerta pública
const alertaPanel = `  {
    id: "at-alertas-panel",
    transicion: "deslizar",
    tipo: "captura",
    titulo: "Cómo se arma una alerta",
    captura: "alerta-temprana/panel-alertas.png",
    puntos: [
      "El sistema lee solo los avisos del SMN y los lista a la izquierda.",
      "«Usar como base» los carga en el mapa para revisarlos.",
      "Se corrige, se publica y se genera la placa para redes.",
