const fs = require("fs");
let t = fs.readFileSync("src/slides.data.js", "utf8");
const rep = (id, fn) => { const i0 = t.indexOf(`id: "${id}",`); if (i0 < 0) throw new Error(id); const i1 = t.indexOf("\n  },\n", i0); t = t.slice(0, i0) + fn(t.slice(i0, i1)) + t.slice(i1); };
const puntos = (a) => "puntos: [\n" + a.map((x) => "      " + JSON.stringify(x) + ",").join("\n") + "\n    ],";
const notas = (s) => "notas:\n      " + JSON.stringify(s);
const edit = (id, cap, tit, pts, nt) => rep(id, (s) => {
  s = s.replace(/captura: "[^"]*"/, `captura: "${cap}"`);
  if (tit) s = s.replace(/titulo: "[^"]*"/, `titulo: ${JSON.stringify(tit)}`);
  return s.replace(/puntos: \[[\s\S]*?\],/, () => puntos(pts)).replace(/notas:\s*"[^"]*"/, () => notas(nt));
});
edit("eco-mapa", "ecodatos/mapa-reportes.png", "Distribución geográfica de los registros",
 ["Cada registro se ubica en el mapa; el número es la cantidad en la zona.", "Los grupos se abren al acercar, hasta llegar al punto.", "La leyenda y los colores corresponden a la variable analizada."],
 "Mapa de los 112 registros de áreas naturales protegidas, agrupados por departamento. Al acercar se separan hasta llegar al marcador individual. Es la capa de puntos de un SIG, con simbología por categoría y leyenda.");
edit("eco-poligonos", "ecodatos/poligonos.png", "Polígonos para los registros",
 ["Se sube una capa GeoJSON (EPSG:4326), por ejemplo exportada desde QGIS.", "Cada polígono se agrega al registro que le corresponde.", "Hasta 5000 polígonos por archivo."],
 "Pestaña de agregar polígonos: no crea registros, le suma a cada registro existente su polígono. Se acepta GeoJSON en EPSG:4326, como lo exporta un SIG de escritorio.");
edit("eco-importar", "ecodatos/importar.png", null,
 ["CSV o GeoJSON con las columnas del formulario, con plantilla para bajar.", "Departamento y municipio por nombre, sin códigos.", "Se valida antes de guardar: si algo falla, no se guarda nada."],
 "Mucho dato histórico vive en planillas. El cajón de importación explica las columnas, ofrece una plantilla y valida todo antes de guardar. Lo viejo también entra al mismo modelo.");
edit("eco-estadisticas", "ecodatos/estadisticas.png", null,
 ["Se elige período, variable y tipo de gráfico.", "Gráfico y tabla se actualizan al instante, con porcentaje del total.", "Debajo del gráfico, el mismo dato se ve en el mapa."],
 "El mapa responde dónde; las estadísticas responden cuánto. En la captura, áreas naturales protegidas por departamento. Es estadística zonal sobre las unidades territoriales.");
const panel = `  {
    id: "eco-panel",
    transicion: "giro",
    tipo: "captura",
    titulo: "Un panel de gestión",
    captura: "ecodatos/panel.png",
    puntos: [
      "Cada área del observatorio tiene su tarjeta con sus formularios.",
      "Cada formulario es una tabla, con carga de registros, tabla y estadísticas.",
      "Acceso por usuario, con permisos de edición o solo lectura.",
    ],
    notas: "Panel de gestión de Ecodatos. Cada tarjeta es un área y agrupa sus formularios; cada formulario es una tabla de la base con su ubicación. Los permisos son por usuario.",
  },
`;
const k = t.indexOf(`  {\n    id: "eco-mapa",`);
t = t.slice(0, k) + panel + t.slice(k);
fs.writeFileSync("src/slides.data.js", t);
EOF
