import puppeteer from "puppeteer-core";
const esp = (ms) => new Promise((r) => setTimeout(r, ms));
const br = await puppeteer.launch({ executablePath: "/usr/bin/google-chrome", headless: "new", userDataDir: process.cwd() + "/perfil4", args: ["--no-sandbox", "--hide-scrollbars", "--use-gl=swiftshader", "--enable-unsafe-swiftshader"] });
const p = await br.newPage(); await p.setViewport({ width: 1600, height: 1000 });
const T = "http://localhost:5175/formularios/area/areas_naturales_protegidas/";
await p.goto(T + "tabla/areas_naturales_protegidas", { waitUntil: "networkidle2", timeout: 60000 }); await esp(10000);
await p.evaluate(() => [...document.querySelectorAll("button")].find((b) => /importar csv/i.test(b.textContent)).click()); await esp(2500);
await p.evaluate(() => [...document.querySelectorAll("label,span,div,button")].filter((b) => /^Agregar polígonos a registros existentes$/i.test(b.textContent.trim())).pop().click()); await esp(2500);
await p.screenshot({ path: "eco/12-poligonos.png" });
await p.goto(T + "stats/areas_naturales_protegidas", { waitUntil: "networkidle2", timeout: 60000 }); await esp(9000);
await p.mouse.click(210, 394); await esp(1200);
await p.evaluate(() => [...document.querySelectorAll("[role=option]")].find((o) => o.textContent.trim() === "Departamento").click()); await esp(7000);
await p.evaluate(() => { const v = document.querySelector(".mantine-ScrollArea-viewport"); v.scrollTo(0, v.scrollHeight); }); await esp(2500);
// botón expandir del mapa (arriba a la derecha de «Distribución geográfica»)
await p.mouse.click(1507, 290); await esp(4000);
await p.screenshot({ path: "eco/13-mapa-grande.png" });
await br.close();

